var txt = String((items[0] && items[0].json) || '');
var hasUA = /user-agent:\s*\*/i.test(txt);
var hasSitemap = /sitemap:/i.test(txt);
var disallows = (txt.match(/^disallow:/gim) || []).length;
var allows = (txt.match(/^allow:/gim) || []).length;
var blocksAssets = /(disallow:\s*\/(wp-content|assets|css|js|static))/i.test(txt);
var issues = [];
if (!hasUA) issues.push('Directive User-agent: * tidak ada');
if (!hasSitemap) issues.push('Directive Sitemap: tidak ada');
if (blocksAssets) issues.push('Ada blokir pada folder asset (CSS/JS)');
return [{ json: {
  valid_structure: hasUA,
  sitemap_declared: hasSitemap,
  disallow_count: disallows,
  allow_count: allows,
  blocks_assets: blocksAssets,
  issues: issues
} }];
